import sys

def main():
    # Read X from standard input
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    X = int(input_data[0])

    total_sum = 0
    # Iterate through rows i from 1 to 9
    for i in range(1, 10):
        # Iterate through columns j from 1 to 9
        for j in range(1, 10):
            val = i * j
            # Add to sum if the value is not X
            if val != X:
                total_sum += val

    print(total_sum)

if __name__ == '__main__':
    main()
